require("modules.monitors")
require("modules.workspace_state")
require("modules.workspaces")
require("modules.autostart")
require("modules.env")
require("modules.layers")
require("modules.misc")
-- Sleek Shell Keyboard settings can disable, remap, and label these binds.
local bindlayer_ok, bindlayer_err = pcall(require, "sleekshell.bindlayer")
if not bindlayer_ok and hl.print then hl.print("[sleek-shell] keybind layer unavailable: " .. tostring(bindlayer_err)) end
require("modules.keybinds")
require("modules.shell_keys")
-- User shortcuts generated by Sleek Shell Settings > Keyboard.
local custom_binds_ok, custom_binds_err = pcall(require, "custom_binds")
if not custom_binds_ok and not tostring(custom_binds_err):find("module .custom_binds. not found") and hl.print then
  hl.print("[sleek-shell] custom shortcuts unavailable: " .. tostring(custom_binds_err))
end
require("modules.decorations")
require("modules.layout")
require("modules.input")
require("modules.windowrules")

-- Your own additions. The installer never ships this file, so upgrades keep it.
local user_ok, user_err = pcall(require, "user")
if not user_ok and not tostring(user_err):find("module .user. not found") and hl.print then
  hl.print("[sleek-shell] user.lua: " .. tostring(user_err))
end

hl.config({
    xwayland = {
        enabled = true,
        force_zero_scaling = true
    }
})
